import{_ as e,o as r,c as o,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Borrowing-money source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/51-borrowing-money-profile.md","filePath":"reference/51-borrowing-money-profile.md","lastUpdated":1788414836000}'),t={name:"reference/51-borrowing-money-profile.md"};function i(s,a,l,d,c,h){return r(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="borrowing-money-source-profile" tabindex="-1">Borrowing-money source profile <a class="header-anchor" href="#borrowing-money-source-profile" aria-label="Permalink to &quot;Borrowing-money source profile&quot;">​</a></h1><h2 id="authority-and-transaction-role" tabindex="-1">Authority and transaction role <a class="header-anchor" href="#authority-and-transaction-role" aria-label="Permalink to &quot;Authority and transaction role&quot;">​</a></h2><p>The <code>borrowing_money</code> activity follows B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter X, “Borrowing Money,” printed page 45 (PDF page 49). It is strictly the borrower or debtor side of taking a loan. Lending money, receiving repayment, investing capital and purchasing inventory are different acts.</p><p>Rama Daivajna&#39;s <em>Muhurta Chintamani</em>, Nakshatra-prakarana verse 27, printed pages 38–39 (OCR lines 2578–2599), was inspected independently. That commentary combines debt-taking with a broader Dravyaprayoga/capital-deployment election and supplies a different Nakshatra/Lagna framework. It does not corroborate Raman&#39;s four-star exclusion set. The disagreement is recorded as <code>muhurta.borrowing.chintamani_divergence</code>; the formulas are not blended.</p><h2 id="automated-rules" tabindex="-1">Automated rules <a class="header-anchor" href="#automated-rules" aria-label="Permalink to &quot;Automated rules&quot;">​</a></h2><p>Raman prohibits borrowing under Krittika, Moola, Punarvasu and Dhanishtha, and also under the individual borrower&#39;s Janma Nakshatra. The four universal stars are hard exclusions. When users supply their birth stars, the Janma-star gate is now enforced identically in Python and the browser.</p><p>No weekday, Tithi, Lagna-class or Choghadiya preference is added: the cited paragraph supplies none.</p><h2 id="manual-chart-and-purpose-checks" tabindex="-1">Manual chart and purpose checks <a class="header-anchor" href="#manual-chart-and-purpose-checks" aria-label="Permalink to &quot;Manual chart and purpose checks&quot;">​</a></h2><ul><li>Avoid Chandra conjoined with Mangala or Shani.</li><li>For quick domestic or personal use, Chandra should favour Lagna.</li><li>For business use, Chandra should favour Budha and the Lagna lord.</li></ul><p>These unresolved chart conditions, and an omitted Janma star, require practitioner review; automated results cannot receive <code>Excellent</code>.</p><h2 id="financial-safety" tabindex="-1">Financial safety <a class="header-anchor" href="#financial-safety" aria-label="Permalink to &quot;Financial safety&quot;">​</a></h2><p>Muhurtam cannot establish affordability or predict repayment success. Repayment capacity, total cost, lender terms, collateral risk and qualified financial or legal advice always take precedence over timing.</p>',12)])])}const m=e(t,[["render",i]]);export{p as __pageData,m as default};
